from __future__ import annotations

import inspect
import logging
import pathlib
import time
from collections.abc import Callable
from concurrent.futures import Future, ThreadPoolExecutor, as_completed
from functools import cached_property, partial
from itertools import chain
from threading import Barrier
from typing import Generic, Iterator, Sequence, TypeVar, ValuesView

from taf.ul.ue.sim.env_setup.devices.airphone import AirPhone
from taf.ul.ue.sim.env_setup.devices.bts import BTS
from taf.ul.ue.sim.env_setup.devices.cloud_bts import CloudBTS
from taf.ul.ue.sim.env_setup.devices.cus import CUS
from taf.ul.ue.sim.env_setup.devices.enb import ENB
from taf.ul.ue.sim.env_setup.devices.gnb import GNB
from taf.ul.ue.sim.env_setup.devices.iphy import Iphy
from taf.ul.ue.sim.env_setup.devices.rtg import RTG
from taf.ul.ue.sim.env_setup.settings import PACKAGE_NAME, RECOVERY_LOG_NAME
from taf.ul.ue.sim.env_setup.telemetry import get_telemetry_instance
from taf.ul.ue.sim.env_setup.utils.enums import DevicesNames
from taf.ul.ue.sim.env_setup.utils.tools import get_ip_address, get_time_diff, opt_bool, resolve_to_ip

telemetry = get_telemetry_instance()
_T_BTS = TypeVar("_T_BTS", GNB, ENB, covariant=False)
_T_CLOUD_BTS = TypeVar("_T_CLOUD_BTS", GNB, ENB, CloudBTS, covariant=False)
_T_SIMS = TypeVar("_T_SIMS", Iphy, AirPhone, RTG, CUS, covariant=False)
_T_DEVICES = TypeVar("_T_DEVICES", GNB, ENB, CloudBTS, Iphy, AirPhone, RTG, CUS, covariant=False)


class DeviceTypedDict(Generic[_T_BTS, _T_SIMS], dict):
    bts: Iterator[ValuesView[_T_BTS]]
    simulator: ValuesView[_T_SIMS]


class HostConfigurator:
    def __init__(
        self,
        node_id: str,
        tl_configuration: dict,
        master_node_ip: str,
        user_flags: dict,
        config_type: str,
    ) -> None:
        self._master_node_ip: str = master_node_ip
        self._processes: list = []
        self._tl_configuration: dict = tl_configuration
        self._node_id: str = node_id
        self._remote_host: str = ""
        self._enbs: dict = {}
        self._gnbs: dict = {}
        self._cloud_btses: dict = {}
        self._airphones: list[AirPhone] = []
        self._cuses: list[CUS] = []
        self._iphyes: list[Iphy] = []
        self._rtgs: list[RTG] = []
        self._output_directory_path: str = ""
        self._suite_config_dir: str = ""
        self._lua_path: str = ""
        self._user_flags: dict = user_flags
        self._config_type: str = config_type
        self.logger: logging.Logger = logging.getLogger(f"{PACKAGE_NAME}.{self.remote_host}")
        self.logger_recovery = logging.getLogger(f"{RECOVERY_LOG_NAME}.{self.remote_host}")

    @property
    def _simulators(self) -> dict:
        return dict(enumerate(chain(self._airphones, self._cuses, self._iphyes, self._rtgs), start=1))

    @cached_property
    def bts_to_simulator_map(self) -> dict[str, list[int]]:
        """

        :return:
        """
        _bts_to_simulator_map = {}
        for bts_id in chain(self._enbs.keys(), self._gnbs.keys()):
            _bts_to_simulator_map[bts_id] = [sim_id for sim_id, sim in self._simulators.items() if sim.connected_bts_id == bts_id]
        return _bts_to_simulator_map

    @cached_property
    def remote_host(self) -> str:
        """Gets IP of Hosted VM"""
        if self._config_type == "ute":
            host_ip = self._get_lmp_ip_for_ute()
        elif self._config_type == "taf":
            host_ip = self._get_lmp_ip_for_taf()
        else:
            host_ip = "127.0.0.1"
        return resolve_to_ip(host_ip) if host_ip != "127.0.0.1" else get_ip_address("eth0")

    def _get_btses(self):
        return chain(self._gnbs.values(), self._enbs.values(), self._cloud_btses.values())

    def _get_classical_btses(self):
        return chain(self._gnbs.values(), self._enbs.values())

    def _get_lmp_ip_for_ute(self):
        return self._tl_configuration["host"].addr

    def _get_lmp_ip_for_taf(self):
        return self._tl_configuration["host"].default_ssh_connection_details.addr

    def get_all_devices(self) -> Iterator[_T_DEVICES]:
        return chain(self._enbs.values(), self._gnbs.values(), self._cloud_btses.values(), self._simulators.values())

    def get_devices(self) -> DeviceTypedDict:
        return DeviceTypedDict(
            bts=self._get_btses(),
            simulator=self._simulators.values(),
        )

    @telemetry.trace("configure_simulators")
    def configure_simulators(self) -> None:
        self._perform_action(self._configure_simulators)

    @telemetry.trace("precondition_for_full_rack")
    def precondition_for_full_rack(self):
        self._perform_action(self._precondition_for_full_rack)

    @telemetry.trace("wait_for_devices_to_sync")
    def wait_for_devices_to_sync(self, barrier: Barrier):
        self._perform_action(partial(self._wait_for_devices_to_sync, barrier))

    @telemetry.trace("configure_btses")
    def configure_btses(self):
        self._perform_action(self._configure_btses)

    def _perform_action(self, fn):
        try:
            fn()
        except Exception as exc:
            self.logger.error(exc, exc_info=True)
            raise

    def _precondition_for_full_rack(self) -> None:
        for bts in self._get_classical_btses():
            if bts.is_already_full_rack_config():
                return
            if self._user_flags.get("config_removal", "").lower() == "skip":
                self.logger.debug("Config removal skipped")
                continue
            bts.reset_config_for_full_rack()

    def _configure_btses(self) -> None:
        for bts in self._get_btses():
            bts.configure()

    def _swap_lmp_for_secondary_bts(self):
        for bts in self._get_btses():
            bts.swap_lmp_for_secondary_bts()

    def _configure_simulators(self) -> None:
        for simulator in self._simulators.values():
            if simulator.name.upper() in (DevicesNames.IPHY, DevicesNames.AIRPHONE):
                self._update_iphy_or_airphone(simulator)
            elif simulator.name.upper() in (DevicesNames.CUS, DevicesNames.RTG) and simulator.idx == 1:
                simulator.configure(
                    self._user_flags.get("warning_lookup", False),
                    self._user_flags.get("skip_restart", False),
                    self.has_airphone(),
                )

    def get_iphy(self, idx: int = 1) -> Iphy:
        """

        :param idx:
        :return:
        """
        try:
            dev = self._iphyes[idx - 1]
        except IndexError:
            dev = Iphy(
                idx=idx,
                configuration=self._tl_configuration[DevicesNames.IPHY][idx - 1],
                remote_host=self.remote_host,
                output_directory_path=self._output_directory_path,
                config_type=self._config_type,
            )
            self._iphyes.append(dev)
        return dev

    def get_airphone(self, idx: int = 1) -> AirPhone:
        """

        :param idx:
        :return:
        """
        try:
            config = self._tl_configuration[DevicesNames.AIRPHONE][idx - 1]
        except (IndexError, KeyError):
            config = self._tl_configuration[DevicesNames.SIMULATOR][idx - 1]
        try:
            dev = self._airphones[idx - 1]
        except IndexError:
            dev = AirPhone(
                idx=idx,
                configuration=config,
                remote_host=self.remote_host,
                output_directory_path=self._output_directory_path,
                config_type=self._config_type,
            )
            self._airphones.append(dev)
        return dev

    def get_device(self, idx: int, device_type: DevicesNames) -> BTS | CloudBTS | AirPhone | Iphy | CUS | RTG:
        devices: dict[DevicesNames, Callable[[int], BTS | CloudBTS | AirPhone | Iphy | CUS | RTG]] = {
            DevicesNames.ENB: self.get_enb,
            DevicesNames.GNB: self.get_gnb,
            DevicesNames.CLOUD_BTS: self.get_cloud_bts,
            DevicesNames.CUS: self.get_cus,
            DevicesNames.AIRPHONE: self.get_airphone,
            DevicesNames.IPHY: self.get_iphy,
            DevicesNames.RTG: self.get_rtg,
        }
        try:
            return devices[device_type](idx)
        except KeyError:
            raise ValueError(f"Unsupported type of device '{device_type}'")

    def get_bts(self, idx: int, bts_type: DevicesNames) -> BTS | CloudBTS:
        if bts_type == DevicesNames.ENB:
            return self.get_enb(idx)
        elif bts_type == DevicesNames.GNB:
            return self.get_gnb(idx)
        elif bts_type == DevicesNames.CLOUD_BTS:
            return self.get_cloud_bts(idx)
        else:
            raise ValueError(f"Unknown BTS type {bts_type}")

    def get_cloud_bts(self, idx: int) -> CloudBTS:
        if (dev := self._cloud_btses.get(idx, None)) is None:
            dev = CloudBTS(
                idx=idx,
                configuration=self._tl_configuration[DevicesNames.CLOUD_BTS][idx - 1],
                bts_id=self._node_id,
                remote_host=self.remote_host,
                output_directory_path=pathlib.Path(self._output_directory_path),
                config_type=self._config_type,
                user_flags=self._user_flags,
            )
            self._cloud_btses[idx] = dev
        return dev

    def get_gnb(self, idx: int) -> GNB:
        if (dev := self._gnbs.get(idx, None)) is None:
            dev = GNB(
                idx=idx,
                configuration=self._tl_configuration[DevicesNames.GNB][idx - 1],
                bts_id=self._node_id,
                remote_host=self.remote_host,
                output_directory_path=self._output_directory_path,
                config_type=self._config_type,
                user_flags=self._user_flags,
            )
            self._gnbs[idx] = dev
        return dev

    def get_enb(self, idx: int) -> ENB | GNB:
        """

        :param idx:
        :return:
        """
        try:
            if (enb := self._enbs.get(idx, None)) is None:
                enb = ENB(
                    idx=idx,
                    configuration=self._tl_configuration[DevicesNames.ENB][idx - 1],
                    bts_id=self._node_id,
                    remote_host=self.remote_host,
                    output_directory_path=self._output_directory_path,
                    config_type=self._config_type,
                    user_flags=self._user_flags,
                )
                self._enbs[idx] = enb
            return enb
        except (IndexError, KeyError):
            try:
                # ugly hack to make LO_CUS_LO and LO_AP_LO work together as dual-label TL
                if (gnb := self._gnbs.get(idx, None)) is None:
                    gnb = GNB(
                        idx=idx,
                        configuration=self._tl_configuration[DevicesNames.GNB][idx - 1],
                        bts_id=self._node_id,
                        remote_host=self.remote_host,
                        output_directory_path=self._output_directory_path,
                        config_type=self._config_type,
                        user_flags=self._user_flags,
                    )
                self._gnbs[idx] = gnb
                return gnb
            except Exception as exc:
                self.logger.error(f"Neither enb nor gnb in tl_configuration: {self._tl_configuration}")
                self.logger.error(exc, exc_info=True)
                raise

    def get_rtg(self, idx: int = 1) -> RTG:
        """

        :param idx:
        :return:
        """
        try:
            dev = self._rtgs[idx - 1]
        except IndexError:
            dev = RTG(
                idx=idx,
                remote_host=self.remote_host,
                output_directory_path=self._output_directory_path,
                configuration=self._tl_configuration[DevicesNames.RTG][idx - 1],
                config_type=self._config_type,
            )
            self._rtgs.append(dev)
        return dev

    def get_cus(self, idx: int = 1) -> CUS:
        """

        :param idx:
        :return:
        """
        try:
            config = self._tl_configuration[DevicesNames.CUS][idx - 1]
        except (IndexError, KeyError):
            config = self._tl_configuration[DevicesNames.SIMULATOR][idx - 1]
        try:
            dev = self._cuses[idx - 1]
        except IndexError:
            dev = CUS(
                idx=idx,
                remote_host=self.remote_host,
                output_directory_path=self._output_directory_path,
                configuration=config,
                config_type=self._config_type,
            )
            self._cuses.append(dev)
        return dev

    def has_cus(self) -> bool:
        """
        :return:
        """
        return any(simulator.name.upper() == DevicesNames.CUS for simulator in self._simulators.values())

    def has_airphone(self) -> bool:
        """
        :return:
        """
        return any(simulator.name.upper() == DevicesNames.AIRPHONE for simulator in self._simulators.values())

    def _log_header(self, msg: str) -> None:
        self.logger.info("{}".format("*" * 50))
        self.logger.info(f"{msg}")
        self.logger.info("{}".format("*" * 50))

    def update_configuration_paths(self, output_directory_path: str, suite_config_dir: str) -> None:
        """

        :param output_directory_path:
        :param suite_config_dir:
        :return:
        """
        for device in self.get_all_devices():
            self.logger.debug(f"Updating configuration paths for {device.name}")
            device.output_directory_path = output_directory_path
            device.suite_config_dir = suite_config_dir
        self._output_directory_path = output_directory_path
        self._suite_config_dir = suite_config_dir

    def _update_iphy_or_airphone(self, simulator: Iphy | AirPhone) -> None:
        if not simulator.sim_xml_path:
            self.logger.debug(f"sim_xml_path for iphy/airphone {str(simulator)} not set. Not doing anything.")
            return
        target_bd = self._get_targetbd_from_bts(simulator)
        simulator.configure(target_bd, self._user_flags["skip_restart"])

    def _get_targetbd_from_bts(self, simulator):
        bts_id = simulator.connected_bts_id
        if not any(self._enbs or self._gnbs or self._cloud_btses):
            self.logger.debug("No btses are configured - targetbd cannot be obtained!")
            return None
        bts = self._enbs[bts_id] if self._enbs else self._gnbs[bts_id] if self._gnbs else self._cloud_btses[bts_id]
        try:
            return bts.targetbd
        except Exception as err:
            self.logger.debug(err)
            bts.recover_ssh()
            return bts.targetbd

    def _execute_task_in_parallel(self, task_list: Sequence[Callable], timeout: int = 5 * 60) -> None:
        futures: list[Future] = []
        if not task_list:
            return self._log_caller_func_name()
        with ThreadPoolExecutor(max_workers=len(task_list)) as thp_executor:
            for task in task_list:
                futures.append(thp_executor.submit(task))
            try:
                for future in as_completed(futures, timeout=timeout):
                    future.result()
            except Exception as err:
                self.logger.warning(err, exc_info=True)
                raise

    def _log_caller_func_name(self) -> None:
        if (current_frame := inspect.currentframe()) is not None and (f_back := current_frame.f_back):
            caller_func_name = inspect.getframeinfo(f_back).function
            self.logger.debug(f"No tasks to perform. Called by {caller_func_name}")
        return

    def _wait_for_rmods(self, timeout: float) -> None:
        for bts in self._get_btses():
            bts.wait_for_rmods_up(timeout)

    def _wait_for_lmp_interfaces(self, skip_unavailable: bool = False) -> None:
        wait_for_lmp_tasks = []
        devices = self.get_all_devices() if self._is_classical_bts() else self._simulators.values()
        ping_timeout, ssh_timeout = 300, 60
        for device in devices:
            wait_for_lmp_tasks.append(
                partial(
                    device.wait_for_interfaces_and_ssh,
                    ping_timeout=ping_timeout,
                    ssh_timeout=ssh_timeout,
                    skip_unavailable=skip_unavailable,
                )
            )
        self._execute_task_in_parallel(wait_for_lmp_tasks, timeout=ping_timeout + ssh_timeout + 10)  # 10s extra for calculations and stuff

    def reset_devices(self, bts_only: bool = False, sim_only: bool = False) -> None:
        """

        :param bts_only:
        :param sim_only:
        :return:
        """
        self._log_header("REBOOT DEVICES")

        def _get_devices():
            if bts_only:
                devices = self._get_btses()
            elif sim_only:
                devices = self._simulators.values()
            else:
                devices = self.get_all_devices()
            return devices

        for device in _get_devices():
            device.reset()

    def create_devices(self) -> None:
        """

        :return:
        """
        self._create_btses()
        self._create_simulators()

    def _create_btses(self) -> None:
        for bts_type in [DevicesNames.ENB, DevicesNames.GNB, DevicesNames.CLOUD_BTS]:
            if bts_type in self._tl_configuration:
                for idx, _ in enumerate(self._tl_configuration[bts_type], start=1):
                    self.get_bts(idx, bts_type)
                    # todo fix -> get rid of get_bts

    def _create_simulators(self) -> None:
        for sim_type in [DevicesNames.CUS, DevicesNames.IPHY, DevicesNames.AIRPHONE]:
            if sim_type in self._tl_configuration:
                for idx, _ in enumerate(self._tl_configuration[sim_type], start=1):
                    getattr(self, f"get_{sim_type.lower()}")(idx)

    def _is_full_rack(self):
        return any(bts._is_full_rack() for bts in self._get_classical_btses())

    def _wait_for_devices_to_sync(self, barrier: Barrier) -> None:
        try:
            self.__wait_for_devices_to_sync()
            if self._is_full_rack():
                self.logger.debug("It's full rack, going to wait for other half")
                barrier.wait()
        except Exception as err:
            if self._is_full_rack():
                self.logger.debug("It's full rack, error caught, aborting barrier.")
                barrier.abort()
            self.logger.debug(err, exc_info=True)
            self.logger_recovery.info(err)
            if self._is_classical_bts():
                self.reset_devices_and_wait_for_sync()
            else:
                self.logger.warning("No recovery for wait for RMODs on cloud bts")
                raise

    def __wait_for_devices_to_sync(self, skip_unavailable=True):
        self._wait_for_lmp_interfaces(skip_unavailable=skip_unavailable)
        if opt_bool(self._user_flags.get("rmod_detection", True)):
            rmod_detection_timeout = int(self._user_flags.get("rmod_detection_timeout", 60 * 15))
            self._wait_for_rmods(rmod_detection_timeout)
            # todo add synchronization check for simulators
        else:
            self.logger.debug("Rmod detection off, skipping to the next step")

    def validate_bts(self, timeout: int) -> None:
        start_time = time.time()
        validate_enb = self._user_flags["validate_enb"]
        validate_gnb = self._user_flags["validate_gnb"]
        validate_cloud_bts = self._user_flags["validate_cloud_bts"]
        if validate_enb:
            for enb in chain(self._enbs.values()):
                enb.ensure_on_air_state(get_time_diff(start_time, timeout))
        if validate_gnb:
            for gnb in chain(self._gnbs.values()):
                gnb.ensure_on_air_state(get_time_diff(start_time, timeout))
        if validate_cloud_bts:
            for cloud_bts in self._cloud_btses.values():
                cloud_bts.ensure_on_air_state(get_time_diff(start_time, timeout))

    def reset_devices_and_wait_for_sync(self):
        self.reset_devices()
        self.__wait_for_devices_to_sync(skip_unavailable=False)

    def _is_classical_bts(self):
        return self._enbs or self._gnbs
